1	// A todo has: id, title, done, createdAt. No due date, no tags, no owner.
2	// Saving and importing decisions live in backup.js (persist, importBackup); this file only wires them to the page.
3	let todos = store.load().todos;
4	let filter = 'all';
5	
6	const $ = (sel) => document.querySelector(sel);
7	
8	function add(title) {
9	  todos.push({ id: crypto.randomUUID(), title: title.trim(), done: false, createdAt: Date.now() });
10	  commit();
11	}
12	
13	function toggle(id) {
14	  const t = todos.find((x) => x.id === id);
15	  if (t) t.done = !t.done;
16	  commit();
17	}
18	
19	function rename(id, title) {
20	  const t = todos.find((x) => x.id === id);
21	  if (!t) return render();
22	  const old = t.title;
23	  t.title = title.trim();
24	  // A failed save keeps its own message; after a read error ('skipped') the banner already says nothing is saved.
25	  if (commit().message || store.readError) return;
26	  offerUndo(`Đã đổi tên thành “${t.title}”.`, () => {
27	    t.title = old;
28	    commit();
29	  });
30	}
31	
32	// policy-ux#U2: an action on one item happens at once and offers Undo for 10 seconds. Any later message
33	// (show() sets textContent) removes the button too.
34	let undoTimer;
35	function offerUndo(message, undo) {
36	  show(message);
37	  const button = document.createElement('button');
38	  button.type = 'button';
39	  button.textContent = 'Hoàn tác';
40	  button.onclick = () => {
41	    clearTimeout(undoTimer);
42	    undo();
